function isProgrammedService(s){const t=s&&s.scheduled_for?new Date(s.scheduled_for).getTime():NaN;return Number.isFinite(t)&&t-Date.now()>PROGRAMMED_AHEAD_MS&&['pending','assigned'].includes(normalizedStatus(s.status))&&!s.trip_id&&!isDriverActivated(s)}
function programmedWhen(s){const d=new Date(s.scheduled_for),tz='America/Argentina/Buenos_Aires',key=x=>new Intl.DateTimeFormat('en-CA',{timeZone:tz}).format(x),hm=d.toLocaleTimeString('es-AR',{hour:'2-digit',minute:'2-digit',hour12:false,timeZone:tz});if(key(d)===key(new Date()))return`hoy ${hm}`;if(key(d)===key(new Date(Date.now()+864e5)))return`mañana ${hm}`;const wd=d.toLocaleDateString('es-AR',{weekday:'short',timeZone:tz}).replace('.',''),dm=d.toLocaleDateString('es-AR',{day:'2-digit',month:'2-digit',timeZone:tz});return`${wd} ${dm} ${hm}`}
