const concept=id=>S.concepts.find(x=>String(x.concept_id)===String(id));
const service=id=>S.services.find(x=>String(x.service_id)===String(id));
async function openSignedRemito(id){
  const svc=service(id);
  if(svc?.status==='completed'&&!svc.remito_id)return viewService(id);
  if(canManage()&&!['completed','cancelled'].includes(svc?.status)&&typeof window.editarServicioOperador==='function')return window.editarServicioOperador(id);
  /* Remito ya aprobado (servicio finalizado, Historial): se abre el remito de verdad (detalle, encuesta, cambios, PDF y WhatsApp) y no la pantalla de "Revisión y cierre", que es para decidir. */
  if(svc?.status==='completed'&&svc.remito_id&&window.RemitoPanel?.open)return window.RemitoPanel.open(Number(svc.remito_id));
  const cerrado=svc?.status==='completed';
  try{
    if(!window.AuxiliosRemitoReviewV2?.open){
      if(typeof window.loadAuxiliosModule!=='function')throw new Error('El cargador del visor no está disponible');
      await window.loadAuxiliosModule('auxilios-operator-remito-review-v2','/operator-remito-review-v2.js');
    }
    if(!window.AuxiliosRemitoReviewV2?.open)throw new Error('El visor del remito no pudo iniciarse');
    return await window.AuxiliosRemitoReviewV2.open(id,{readOnly:cerrado});
  }catch(error){
    console.error('[Servicios] No se pudo abrir el remito firmado:',error);
    notify(error?.message||'No se pudo abrir el remito firmado','error');
  }
}
function dateParts(v){if(!v)return{day:'—',time:'—'};const d=new Date(v),parts=new Intl.DateTimeFormat('es-AR',{timeZone:'America/Argentina/Buenos_Aires',day:'2-digit',month:'2-digit',year:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(d),g=t=>parts.find(p=>p.type===t)?.value||'';return{day:`${g('day')}/${g('month')}/${g('year')}`,time:`${g('hour')}:${g('minute')}`};}
const fmtDay=v=>dateParts(v).day,fmtTime=v=>dateParts(v).time;
const fmtMoney=v=>new Intl.NumberFormat('es-AR',{style:'currency',currency:'ARS',maximumFractionDigits:2}).format(num(v));
const activeServices=()=>S.services.filter(x=>isDriverActivated(x)?!['completed','cancelled'].includes(x.status):ACTIVE.has(x.status)||pendingRemitoReview(x));
const historyServices=()=>S.services.filter(x=>(x.status==='completed'&&(isDriverActivated(x)||!pendingRemitoReview(x)))||(x.status==='cancelled'&&S.moduleConfig.workflow.show_cancelled_in_history!==false));
function normalizedOrder(value){if(!Array.isArray(value)||!value.length||value.some(k=>!COLUMN_KEYS.includes(k)))return DEFAULT_CONFIG.column_order.slice();const unique=[...new Set(value)];return unique.concat(COLUMN_KEYS.filter(k=>!unique.includes(k)));}
function normalizeConfig(data){const x=data||{},fieldModes={};for(const key of Object.keys(DEFAULT_CONFIG.field_modes)){const mode=x.field_modes?.[key];fieldModes[key]=['required','optional','hidden'].includes(mode)?mode:DEFAULT_CONFIG.field_modes[key];}return{column_order:normalizedOrder(x.column_order),column_visibility:Object.fromEntries(COLUMN_KEYS.map(k=>[k,typeof x.column_visibility?.[k]==='boolean'?x.column_visibility[k]:DEFAULT_CONFIG.column_visibility[k]])),location_detail:{address:typeof x.location_detail?.address==='boolean'?x.location_detail.address:DEFAULT_CONFIG.location_detail.address,locality:typeof x.location_detail?.locality==='boolean'?x.location_detail.locality:DEFAULT_CONFIG.location_detail.locality,province:typeof x.location_detail?.province==='boolean'?x.location_detail.province:DEFAULT_CONFIG.location_detail.province},field_modes:fieldModes,workflow:{...DEFAULT_CONFIG.workflow,...(x.workflow||{})}};}
async function loadModuleConfig(){if(S.settingsLoaded)return;const module=window.AuxiliosServiceModuleConfiguration;if(module?.load)await module.load();if(module?.get)S.moduleConfig=normalizeConfig(module.get());S.settingsLoaded=true;}
