function personalKey(){return`auxilios.services.columns.${currentUserId()||'local'}`;}
function normalizePersonalPreference(raw){if(!raw||!Array.isArray(raw.column_order)||raw.column_order.some(k=>!COLUMN_KEYS.includes(k)))return null;return{column_order:normalizedOrder(raw.column_order),column_visibility:Object.fromEntries(COLUMN_KEYS.map(k=>[k,typeof raw.column_visibility?.[k]==='boolean'?raw.column_visibility[k]:DEFAULT_CONFIG.column_visibility[k]])),location_detail:{address:typeof raw.location_detail?.address==='boolean'?raw.location_detail.address:DEFAULT_CONFIG.location_detail.address,locality:typeof raw.location_detail?.locality==='boolean'?raw.location_detail.locality:DEFAULT_CONFIG.location_detail.locality,province:typeof raw.location_detail?.province==='boolean'?raw.location_detail.province:DEFAULT_CONFIG.location_detail.province},density:raw.density==='wide'?'wide':'compact'};}
function readPersonalCache(){try{return normalizePersonalPreference(JSON.parse(localStorage.getItem(personalKey())||'null'));}catch{return null;}}
function writePersonalCache(pref){try{if(pref)localStorage.setItem(personalKey(),JSON.stringify(pref));else localStorage.removeItem(personalKey());}catch{/* caché local no crítica */}}
async function loadPersonalPreference(){if(S.personalPreferenceLoaded)return S.personalPreference;const uid=currentUserId();if(!uid||typeof _db==='undefined')return null;const cached=readPersonalCache();try{const {data,error}=await _db.from('user_view_preferences').select('preferences').eq('user_id',uid).eq('view_key',PERSONAL_VIEW_KEY).maybeSingle();if(error)throw error;const remote=normalizePersonalPreference(data?.preferences);if(remote){S.personalPreference=remote;writePersonalCache(remote);}else if(cached){const {error:syncError}=await _db.from('user_view_preferences').upsert({user_id:uid,view_key:PERSONAL_VIEW_KEY,preferences:cached,updated_at:new Date().toISOString()},{onConflict:'user_id,view_key'});if(syncError)throw syncError;S.personalPreference=cached;}else S.personalPreference=null;}catch(error){S.personalPreference=cached;console.warn('[Servicios] No se pudo sincronizar la preferencia de columnas:',error?.message||error);}S.personalPreferenceLoaded=true;return S.personalPreference;}
function personalConfig(){if(S.moduleConfig.workflow.allow_personal_column_overrides===false)return null;return S.personalPreference||readPersonalCache();}
