function effectiveColumns(){const p=personalConfig(),base=S.moduleConfig,visibility={...base.column_visibility,...(p?.column_visibility||{})};if(!p&&isNotebookWidth())for(const key of NOTEBOOK_HIDDEN_COLUMNS)visibility[key]=false;return{column_order:p?.column_order||base.column_order,column_visibility:visibility,location_detail:{...base.location_detail,...(p?.location_detail||{})},density:p?.density==='wide'?'wide':'compact'};}
