async function loadReferences(){if(!canRead()||typeof _db==='undefined')return false;const {data,error}=await _db.rpc('get_operator_service_reference_data');if(error)throw error;/* La cuenta interna "Particulares" no es una prestadora: no va en ninguna lista de prestadoras. */S.companies=(Array.isArray(data?.companies)?data.companies:[]).filter(c=>!(c&&(c.client_kind==='particular'||/^particulares$/i.test(String(c.trade_name||c.name||c.legal_name||'').trim()))));S.drivers=Array.isArray(data?.drivers)?data.drivers:[];S.trucks=Array.isArray(data?.trucks)?data.trucks:[];S.concepts=Array.isArray(data?.concepts)?data.concepts:[];S.referencesLoaded=true;if(S.company!=='all'&&!S.companies.some(x=>String(x.company_id)===String(S.company)))S.company='all';renderFilterBar();return true;}
