async function savePersonal(){if(!S.personalDraft)return;const pref=normalizePersonalPreference(S.personalDraft),uid=currentUserId();if(!pref||!uid)return notify('No se pudo identificar la preferencia del usuario','error');S.personalPreference=pref;S.personalPreferenceLoaded=true;writePersonalCache(pref);closePersonalizer();renderServices();try{const {error}=await _db.from('user_view_preferences').upsert({user_id:uid,view_key:PERSONAL_VIEW_KEY,preferences:pref,updated_at:new Date().toISOString()},{onConflict:'user_id,view_key'});if(error)throw error;notify('Vista personal guardada','success');}catch(error){console.error('[Servicios] No se pudo guardar la preferencia de columnas:',error);notify('La vista quedó guardada en este dispositivo, pero no se pudo sincronizar con tu usuario','warning');}}
