function hookNavigation(){
  if(window.__osNavHook||typeof window.goTo!=='function')return false;
  const base=window.goTo;let position={top:0,left:0};
  window.goTo=(name,...args)=>{
    if(name==='operaciones'&&!canRead())return notify('Sin permiso para acceder a Servicios','error');
    const screen=document.getElementById('screen-operaciones'),table=screen?.querySelector('.os-table-wrap');
    if(screen?.classList.contains('active')&&table)position={top:table.scrollTop,left:table.scrollLeft};
    if(name==='operaciones')registerScreenMetadata();
    const result=base(name,...args);
    if(name==='operaciones'){if(table){table.scrollTop=position.top;table.scrollLeft=position.left;}loadServices();}
    return result;
  };
  window.__osNavHook=true;return true;
}
